void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 p = (2.*fragCoord.xy-iResolution.xy) / iResolution.y;
    float a = atan(p.x,p.y);
    float r = length(p);

    // Distortion effect
    float distortion = sin(iTime * 2.0 + r * 20.0) * 0.05;
    r += distortion;

    vec2 uv = vec2(0.0,r);

    uv = (2.0 * uv) -1.0;     
    float pulse = cos(iTime * 2.0) * 0.5 + 1.0;
    float beamWidth = abs(5.0 / (40.0 * uv.y)) * pulse;

    // Golden pulsating color
    vec3 color = vec3(0.957, 0.427, 0.263);
    vec3 horBeam = color * beamWidth;

    fragColor = vec4(horBeam, 1.0);
}
